media/img/7_aforementioned.jpg"},{"word":"aggravate","meaning_vi":"làm trầm trọng thêm, làm nặng thêm","definition":"","phonetic":"/ˈæɡrəveɪt/","audio":null,"image_url":"/media/vocabs_media/img/5_aggravate.jpg"},{"word":"agitate","meaning_vi":"tranh luận, vận động (cho một điều gì, đặc biệt là để thay đổi một điều luật hoặc một điều gì đó trong xã hội)","definition":"","phonetic":"/ˈædʒɪteɪt/","audio":null,"image_url":"/media/vocabs_media/img/7_agitate.jpg"},{"word":"alacrity","meaning_vi":"sự sốt sắng","definition":"","phonetic":"/əˈlækrəti/","audio":null,"image_url":"/media/vocabs_media/img/6_alacrity.jpg"}]',  -- exercise_data (JSON) - đã escape backslash và dấu nháy đơn
    80,  -- exercise_duration (ước tính: 1 phút/từ)
    0,  -- pass_score (không có điểm)
    0,  -- max_score (không có điểm)
    FALSE,  -- is_free
    TRUE,  -- is_active
    0,  -- view_count
    NOW(),
    NOW()
);

-- Kiểm tra kết quả
SELECT 
    lesson_id,
    module_id,
    course_id,
    title,
    lesson_type,
    exercise_type,
    has_exercise,
    JSON_LENGTH(exercise_data) as total_words
FROM lessons 
WHERE lesson_id = 75;
